const project=path.dirname(path.dirname(fileURLToPath(import.meta.url))),root=path.join(project,'src');
const names=['service-catalog.json','THIRD-PARTY-NOTICES.txt','vendor/dfo-formats/LICENSE','PORTABLE.md','dashboard.html','dashboard.css','dashboard-mobile.css','dashboard-mobile.mjs','dashboard-brand.mjs','dashboard-ui.mjs','dashboard-cursor.mjs','dashboard-character.mjs','dashboard-qr.mjs','dashboard-qr-LICENSE.txt','dashboard-items.mjs','upgrade-scoring.mjs','dashboard-extras.mjs','dashboard-alerts.mjs','dashboard-map-ui.mjs','dashboard-map-model.mjs','dashboard-dungeon-route.mjs','dashboard-interior-ui.mjs','dashboard-interior-model.mjs','paperdoll-preview.mjs','paperdoll-composite.mjs','vendor/dfo-formats/dyes.js','reviewed-bundles.json','card-metadata.json','spell-metadata.json','vendor/dfo-formats/map-pages.json','vendor/dfo-formats/paperdoll-templates.json','vendor/dfo-formats/item-art-templates.json'];
for(const folder of ['dashboard-art','dashboard-fonts'])for(const f of await fs.readdir(path.join(root,folder)))if((await fs.stat(path.join(root,folder,f))).isFile())names.push(folder+'/'+f);
const resources={};for(const name of names)resources[name]=(await fs.readFile(path.join(root,name))).toString('base64');
const generated=`import {dirname,join} from 'node:path';import{fileURLToPath}from'node:url';import{homedir}from'node:os';export const RESOURCE_ROOT=dirname(fileURLToPath(import.meta.url));export const CACHE_ROOT=join(process.env.DFO_COMPANION_CACHE??(process.platform==='win32'?process.env.LOCALAPPDATA??join(homedir(),'AppData','Local'):process.platform==='darwin'?join(homedir(),'Library','Caches'):process.env.XDG_CACHE_HOME??join(homedir(),'.cache')),'DFOCompanion');const assets=${JSON.stringify(resources)};export function readResourceSync(name,encoding){if(!Object.hasOwn(assets,name))throw Error('RESOURCE_NOT_EMBEDDED');const b=Buffer.from(assets[name],'base64');return encoding?b.toString(encoding):b;}export async function readResource(name,encoding){return readResourceSync(name,encoding);}`;
const output=path.join(project,'desktop','DFO-Companion.mjs');
await build({stdin:{contents:`import {appendFile,mkdir} from 'node:fs/promises';import {join as logJoin} from 'node:path';import {launchOfficialGame,portableGamePath} from './portable-startup.mjs';import {startDashboard,createDashboardServer} from './dashboard-server.mjs';import {readResource,CACHE_ROOT} from './dashboard-resources.mjs';export {startDashboard,createDashboardServer};if(process.argv.includes('--check-bundle')){const review=JSON.parse(await readResource('reviewed-bundles.json','utf8'));console.log(JSON.stringify({available:true,portable:true,embeddedResources:${names.length},cacheRoot:CACHE_ROOT,reviewPresent:!!review,htmlBytes:(await readResource('dashboard.html')).length}));}else if(process.argv.includes('--check-bundle-http')){const port=19239,server=createDashboardServer({snapshot:()=>({status:'test'})},{port});await new Promise(r=>server.listen(port,'127.0.0.1',r));try{let checked=0;for(const name of ['service-catalog.json','dashboard.html','dashboard.css','dashboard-mobile.css','dashboard-mobile.mjs','dashboard-brand.mjs','dashboard-ui.mjs','dashboard-qr.mjs','dashboard-map-ui.mjs','dashboard-map-model.mjs','dashboard-dungeon-route.mjs','dashboard-interior-ui.mjs','dashboard-interior-model.mjs','dashboard-items.mjs','upgrade-scoring.mjs','dashboard-extras.mjs','paperdoll-preview.mjs','paperdoll-composite.mjs','vendor/dfo-formats/dyes.js','dashboard-fonts/pixelify-sans.woff2','dashboard-fonts/pixelify-five.woff2','dashboard-fonts/pixelify-glyphs.woff2','dashboard-art/game-frame.svg','dashboard-art/cuirass.png']){const res=await fetch('http://127.0.0.1:'+port+'/'+(name==='dashboard.html'?'':name));if(!res.ok||!Buffer.from(await res.arrayBuffer()).equals(await readResource(name)))throw Error('EMBEDDED_HTTP_MISMATCH '+name);checked++;}console.log(JSON.stringify({available:true,embeddedHttpAssets:checked,gameAttached:false}));}finally{await new Promise(r=>server.close(r));}}else if(!process.env.DFO_COMPANION_EMBEDDED){try{if(process.argv.includes('--launch-game'))await launchOfficialGame({gamePath:portableGamePath(process.argv.slice(2))});await startDashboard({open:process.argv.includes('--open')});}catch(e){const message=new Date().toISOString()+' DFO Companion: '+e.message;console.error(message);try{await mkdir(CACHE_ROOT,{recursive:true});await appendFile(logJoin(CACHE_ROOT,'startup.log'),message+String.fromCharCode(10));}catch{}process.exitCode=1;}}`,resolveDir:root,sourcefile:'portable-entry.mjs'},outfile:output,bundle:true,platform:'node',format:'esm',target:'node22',legalComments:'inline',minify:false,plugins:[{name:'portable-resources',setup(b){b.onLoad({filter:/dashboard-resources\.mjs$/},()=>({contents:generated,loader:'js'}));b.onLoad({filter:/\.(?:mjs|js)$/},async args=>{if(!args.path.startsWith(root))return;let text=await fs.readFile(args.path,'utf8');text=text.replaceAll('process.argv[1]&&import.meta.url===pathToFileURL(process.argv[1]).href','false');text=text.replace(/JSON\.parse\((?:fs\.)?readFileSync\(new URL\('([^']+)',import\.meta\.url\),'utf8'\)\)/g,(full,name)=>{const key=path.posix.normalize(name);if(!resources[key])throw Error('MISSING_JSON '+key);return Buffer.from(resources[key],'base64').toString('utf8');});if(path.basename(args.path)==='cached-module.mjs')text=text.replace("await readFile(reviewedPath,'utf8')",JSON.stringify(Buffer.from(resources['reviewed-bundles.json'],'base64').toString()));return {contents:text,loader:'js',resolveDir:path.dirname(args.path)};});}}]});

const pkg=JSON.parse(await fs.readFile(path.join(project,'package.json'),'utf8'));const id=(await import('node:crypto')).createHash('sha256').update(await fs.readFile(output)).digest('hex').slice(0,12);await fs.writeFile(path.join(project,'desktop/build.json'),JSON.stringify({id,label:'v'+pkg.version+' · '+id,version:pkg.version,macAutoUpdateReady:process.env.MAC_SIGNED==='true'},null,2));console.log(JSON.stringify({version:pkg.version,id,resources:names.length,bytes:(await fs.stat(output)).size}));
